{
  "aktywnosci": [
    {
      "tytul": "Słuchamy ciszy – zabawa sensoryczna",
      "opis": "Dzieci siadają w kole na dywanie. Nauczyciel mówi: „Za chwilę zrobimy się cicho jak myszki i posłuchamy, co słychać w ciszy”. Po minucie ciszy dzieci opowiadają, co usłyszały (np. tik-tak zegara, szum kaloryfera, oddech kolegi). Zabawę powtarzamy 2–3 razy, za każdym razem wydłużając czas nasłuchiwania. Można użyć małego dzwoneczka jako sygnału do rozpoczęcia i zakończenia ciszy."
    },
    {
      "tytul": "Ciche obrazki – praca plastyczna z watą",
      "opis": "Nauczyciel rozdaje dzieciom niebieskie kartki, watę i klej. Zadaniem dzieci jest stworzenie „cichego obrazka” – np. chmur, śpiącego kota, gwiazd na niebie – bez rozmawiania. Po skończeniu prac dzieci w ciszy oglądają obrazki kolegów i pokazują gestem, który podoba im się najbardziej. Ćwiczy to skupienie i wyrażanie emocji bez słów."
    },
    {
      "tytul": "Głuchy telefon – zabawa ruchowa z przekazywaniem dźwięku",
      "opis": "Dzieci stoją w rzędzie. Nauczyciel szepcze pierwszej osobie proste hasło (np. „pies”, „słońce”, „miś”). Dziecko przekazuje je szeptem następnemu, a ostatnie mówi na głos, co usłyszało. Potem wszyscy wspólnie sprawdzają, czy hasło się zmieniło. Zabawa uczy uważnego słuchania i kontrolowania własnego głosu. Można powtórzyć kilka razy z różnymi hasłami."
    }
  ]
}
